def transform(grid):
    # The bottom row contains two copies of the sequence, with zeros between.
    # Each isolated marker gives the position at which to place that sequence,
    # rotated to start at the marker's color, continuing cyclically.
    h, w = len(grid), len(grid[0])
    seq = [v for v in grid[-1] if v]
    out = [row[:] for row in grid]
    for r in range(h-1):
        for c, v in enumerate(grid[r]):
            if v:
                try: k = seq.index(v)
                except ValueError: continue
                rotated = seq[k:] + seq[:k]
                for j, x in enumerate(rotated):
                    if c+j < w:
                        out[r][c+j] = x
    return out
